<template><div class="page"><div class="intro"><div><span class="eyebrow">TODAY WORKBENCH</span><h1>今天要做什么</h1><p>把固定运营事项、内容交付和广告提醒放在同一张工作清单里。</p></div></div><section class="workspace-panel"><div class="section-head"><h3>今日待办</h3><span class="muted">{{ tasks.length }} 项</span></div><div class="task-grid"><div v-for="task in tasks" :key="task.key" class="task-item"><el-checkbox v-model="done[task.key]">{{ task.label }}</el-checkbox><span :class="done[task.key] ? 'task-done' : 'task-pending'">{{ done[task.key] ? '已完成' : '待处理' }}</span></div></div></section><div class="ops-grid"><section class="workspace-panel"><div class="section-head"><h3>待处理内容</h3><el-button link type="primary" @click="router.push('/content/mix-projects')">查看方案</el-button></div><div v-for="item in data.content_projects" :key="item.id" class="home-link-row"><span>{{ item.name }}</span><el-button link @click="router.push(`/mix-projects/${item.id}`)">继续编辑</el-button></div><el-empty v-if="!data.content_projects?.length" description="暂无待处理方案" :image-size="50"/></section><section class="workspace-panel"><div class="section-head"><h3>广告提醒</h3><el-button link type="primary" @click="router.push('/ads')">处理广告</el-button></div><div v-for="item in data.ad_alerts" :key="item.id" class="alert-row"><strong>{{ item.plan_name }}</strong><span>{{ item.current_status }}</span></div><el-empty v-if="!data.ad_alerts?.length" description="暂无广告提醒" :image-size="50"/></section></div><section class="workspace-panel"><div class="section-head"><h3>待上传成片</h3><el-button link type="primary" @click="router.push('/content/video-works')">打开视频作品</el-button></div><div v-for="item in data.pending_videos" :key="item.id" class="home-link-row"><span>{{ item.title }}</span><el-button link @click="router.push(`/videos/${item.id}`)">上传成片</el-button></div><el-empty v-if="!data.pending_videos?.length" description="暂无待上传成片" :image-size="50"/></section></div></template>
<script setup lang="ts">import { onMounted, reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import axios from 'axios'; const router=useRouter(); const tasks=ref<any[]>([]); const data=ref<any>({}); const done=reactive<Record<string,boolean>>({}); onMounted(async()=>{data.value=(await axios.get('/api/workbench/today')).data;tasks.value=data.value.tasks||[];tasks.value.forEach(item=>done[item.key]=false);});</script>
